type Criterion = [expected: string, guidance: string];
function q(id: string, unit: string, topic: string, pages: [number, number], authors: string, prompt: string, explanation: string, criteria: Criterion[], options: { caseStudy?: boolean; final?: boolean; extraSource?: string } = {}): Question {
  const file = Number(unit.slice(1)) <= 2 ? "Resumen primer parcial.pdf" : "Resumen segundo parcial.pdf";
  return {
    id: `antro-${id}`, subjectId: "antro", unit, topic, sourcePages: pages,
    type: options.caseStudy ? "case-study" : "development", difficulty: options.final ? "Integración" : options.caseStudy ? "Aplicación" : "Integración",
    finalOnly: options.final,
    prompt, explanation, source: `${file}, pp. ${pages[0]}–${pages[1]} del PDF · ${authors}.${options.extraSource ? ` ${options.extraSource}` : ""}`,
    rubric: criteria.map(([expected]) => expected), writtenCriteria: criteria.map(([expected, guidance]) => ({ expected, guidance })),
  };
}

